const row = $json;

if (!row.article_id) {
  throw new Error('No approved article has a complete WordPress practice configuration.');
}
if (String(row.publisher_type || '').toUpperCase() !== 'WORDPRESS') {
  throw new Error('The selected practice is not configured for the WordPress adapter.');
}

let config = {};
try {
  config = JSON.parse(row.publisher_config_reference);
} catch {
  config = { credential_name: row.publisher_config_reference };
}
if (!config.credential_name) {
  throw new Error('publisher_config_reference must name the n8n WordPress credential or contain JSON with credential_name.');
}

let publicationPackage;
try {
  publicationPackage = typeof row.publication_package_json === 'string'
    ? JSON.parse(row.publication_package_json)
    : row.publication_package_json;
} catch (error) {
  throw new Error('The approved publication package is not valid JSON: ' + error.message);
}

const metadata = publicationPackage?.metadata || {};
let html = String(publicationPackage?.article_html || '');
if (!html || !/<h1(?:\s|>)/i.test(html)) {
  throw new Error('The approved package does not contain publishable article HTML.');
}
if (/<(?:script|style|html|head|body)(?:\s|>)/i.test(html)) {
  throw new Error('The approved article contains a forbidden document or executable tag.');
}

const requireHttpsUrl = (value, label) => {
  const raw = String(value || '').trim();
  const candidate = /^https?:\/\//i.test(raw) ? raw : 'https://' + raw;
  const match = /^https:\/\/([A-Za-z0-9.-]+)(\/[\/A-Za-z0-9._~%!$&'()*+,;=:@-]*)?\/?$/.exec(candidate);
  const host = match?.[1] || '';
  if (!match || !host.includes('.') || host.split('.').some(part => !part || part.startsWith('-') || part.endsWith('-')) || /(^|\.)example\.com$/i.test(host)) {
    throw new Error(label + ' must be an explicitly configured real HTTPS URL without credentials, query, or fragment.');
  }
  return candidate.replace(/\/+$/, '');
};
const publicUrl = requireHttpsUrl(row.website_domain, 'Public static website');
if (!config.wordpress_base_url) {
  throw new Error('WordPress multisite subsite base URL must be configured separately from the public static website.');
}
const wordpressBaseUrl = requireHttpsUrl(config.wordpress_base_url, 'WordPress subsite base');
if (row.practice_id !== 'practice_test_001' || wordpressBaseUrl !== 'https://apexparent.hostmanpowered.com/test001') {
  throw new Error('Automatic publication is restricted to the TEST-1 practice and its verified WordPress subsite.');
}
if (row.practice_id !== 'practice_test_001' || wordpressBaseUrl !== 'https://apexparent.hostmanpowered.com/test001') {
  throw new Error('Automatic publication is restricted to the TEST-1 practice and its verified base configuration.');
}
const pilotCampaign = 'campaign_test_202609_aac_prestonwood_pilot_2026_09_23';
const isPrestonwoodPilot = row.campaign_id === pilotCampaign;
if (isPrestonwoodPilot && String(row.doctor_email || '').toLowerCase() !== 'jdold@apexdp.com') {
  throw new Error('The Prestonwood pilot permits only the named test identity.');
}
const publicationBaseUrl = isPrestonwoodPilot ? 'https://apexparent.hostmanpowered.com/dfw-03' : wordpressBaseUrl;
const appointmentUrl = isPrestonwoodPilot ? 'https://prestonwooddentistry.com' : String(config.appointment_url || publicUrl);
const replacements = {
  '{{DOCTOR_NAME}}': row.doctor_name || '',
  '{{DOCTOR_CREDENTIALS}}': row.credentials || '',
  '{{PRACTICE_NAME}}': '[sc name="practice_name"][/sc]',
  '{{APPOINTMENT_URL}}': appointmentUrl
};
for (const [token, value] of Object.entries(replacements)) {
  html = html.split(token).join(String(value));
}
if (/{{[A-Z0-9_]+}}/.test(html)) {
  throw new Error('The article still contains unresolved publishing tokens.');
}

html = html
  .replace(/^(?:\s*<!--[\s\S]*?-->\s*)+/, '')
  .replace(/\s*<h1[^>]*>[\s\S]*?<\/h1>\s*/i, '\n')
  .trim();

const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, (character) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
}[character]));
const doctorName = String(row.doctor_name || '').trim();
const credentials = String(row.credentials || '').trim();
if (!doctorName) throw new Error('The interviewed doctor name is required for attribution.');
const doctorLabel = credentials ? doctorName + ', ' + credentials : doctorName;
html = html.replace(/<p\b[^>]*class=["'][^"']*\barticle-byline\b[^"']*["'][^>]*>[\s\S]*?<\/p>\s*/gi, '');
const leadingByline = /^\s*<p\b[^>]*>([\s\S]*?)<\/p>\s*/i.exec(html);
if (leadingByline) {
  const leadingBylineText = leadingByline[1]
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&quot;/gi, '"')
    .replace(/\s+/g, ' ')
    .trim();
  if (leadingBylineText.toLowerCase() === ('By ' + doctorLabel).toLowerCase()) {
    html = html.slice(leadingByline[0].length);
  }
}
html = '<p class="article-byline">By <strong>' + escapeHtml(doctorLabel) + '</strong></p>\n' + html;
const featuredImageSourceUrl = requireHttpsUrl(row.featured_image_source_url, 'Featured image central source');
if (!featuredImageSourceUrl.startsWith('https://apexparent.hostmanpowered.com/wp-content/uploads/')) throw new Error('Featured images must come from the designated Apex Parent central Media Library.');
const featuredImageAlt = String(row.featured_image_alt_text || '').trim();
if (!featuredImageAlt) throw new Error('The selected topic image must include useful alt text.');
const faqHeading = /<h2\b[^>]*>[^<]*(?:frequently asked questions|faq)[^<]*<\/h2>/i.exec(html);
if (!faqHeading) throw new Error('The approved article must include a clearly labeled FAQ.');
const faqHtml = html.slice(faqHeading.index);
const faqItems = faqHtml.match(/<h3\b[^>]*>/gi) || [];
if (faqItems.length < 3 || faqItems.length > 6 || /<h2\b/i.test(faqHtml.slice(faqHeading[0].length))) {
  throw new Error('The approved article FAQ must contain 3 to 6 questions and be the final public section.');
}
html = html.replace(/<(section|div)\b[^>]*class=["'][^"']*\barticle-doctor-profile\b[^"']*["'][^>]*>[\s\S]*?<\/\1>\s*/gi, '');
const bio = String(row.doctor_short_bio || '').trim();
const profileUrl = String(row.doctor_profile_url || '').trim();
const photoUrl = String(row.doctor_photo_url || '').trim();
let profile = '<section class="article-doctor-profile"><h2>About ' + escapeHtml(doctorName) + '</h2>';
if (photoUrl) {
  const safePhotoUrl = requireHttpsUrl(photoUrl, 'Doctor profile photo');
  profile += '<figure><img src="' + escapeHtml(safePhotoUrl) + '" alt="' + escapeHtml(doctorName) + '" loading="lazy"></figure>';
}
profile += '<p>' + escapeHtml(bio || (doctorName + ' is the dentist interviewed for this article.')) + '</p>';
if (profileUrl) {
  const safeProfileUrl = requireHttpsUrl(profileUrl, 'Doctor public profile');
  profile += '<p><a href="' + escapeHtml(safeProfileUrl) + '">Read more about ' + escapeHtml(doctorName) + '</a></p>';
}
profile += '</section>';
html = html.slice(0, faqHeading.index) + profile + '\n' + html.slice(faqHeading.index);

const exactPilotQa = String(row.qa_republish).toLowerCase() === 'true'
  && row.article_id === 'article_6296aabf938f492eafd5a2b010b3f8c9'
  && row.campaign_id === 'campaign_test_202609_aac_prestonwood_pilot_2026_09_23';
let title = String(metadata.h1 || '').trim() || String(publicationPackage.article_html).match(/<h1[^>]*>([\s\S]*?)<\/h1>/i)?.[1]?.replace(/<[^>]+>/g, '').trim();
let slug = String(metadata.slug || '').trim();
let seoTitle = String(metadata.seo_title || '').trim();
let excerpt = String(metadata.meta_description || '').trim();
let focusKeyphrase = String(metadata.focus_keyphrase || '').trim();
if (!focusKeyphrase && /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug)) {
  const slugWords = slug.split('-').filter(Boolean);
  if (slugWords.length >= 2 && slugWords.length <= 6) focusKeyphrase = slugWords.join(' ');
}
if (exactPilotQa) {
  title ||= 'Two Dental Cleanings a Year: Too Many, Too Few, or Just Right?';
  slug ||= 'do-you-need-two-dental-cleanings-a-year';
  seoTitle ||= 'How Often Do You Need Dental Cleanings? | Prestonwood';
  excerpt ||= 'Learn how dentists personalize cleaning schedules based on gum health, cavity risk, tartar buildup, and each patient’s preventive care needs.';
  focusKeyphrase ||= 'dental cleaning frequency';
}
if (!title || !seoTitle || !slug || !excerpt || !focusKeyphrase) {
  throw new Error('The approved package is missing its title, SEO title, slug, meta description, or focus keyphrase.');
}
if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug) || slug.length > 75) throw new Error('The slug must be concise lowercase ASCII words separated by hyphens.');
if (excerpt.length < 120 || excerpt.length > 165) throw new Error('The meta description must be 120 to 165 characters.');
if (focusKeyphrase.split(/\s+/).length < 2 || focusKeyphrase.split(/\s+/).length > 6) throw new Error('The focus keyphrase must contain 2 to 6 words.');

return [{ json: {
  ...row,
  credential_name: config.credential_name,
  wordpress_api_url: `${publicationBaseUrl}/wp-json/wp/v2`,
  title, seo_title: seoTitle, slug, excerpt, focus_keyphrase: focusKeyphrase, content: html,
  wordpress_publication_base_url: publicationBaseUrl,
  featured_image_source_url: featuredImageSourceUrl,
  featured_image_alt_text: featuredImageAlt,
  featured_image_media_slug: 'aac-' + String(row.topic_id || row.article_id).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''),
  featured_image_upload_filename: 'aac-' + String(row.topic_id || row.article_id).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') + (featuredImageSourceUrl.match(/\.(?:jpe?g|png|webp)$/i)?.[0].toLowerCase() || '.jpg'),
  wordpress_body: {
    title, content: html, slug, excerpt, status: 'publish',
    ...(config.supports_yoast_meta === true ? { meta: {
      _yoast_wpseo_title: seoTitle,
      _yoast_wpseo_metadesc: excerpt,
      _yoast_wpseo_focuskw: focusKeyphrase
    } } : {}),
    comment_status: 'closed', ping_status: 'closed', format: 'standard'
  }
} }];

const context = $('Attach Uploaded Campaign Image').first().json;
const existing = $input.all().map((item) => item.json).find((post) => post?.id && post?.slug === context.slug);
return [{ json: {
  ...context,
  existing_post_id: existing?.id ? String(existing.id) : null,
  wordpress_publish_url: existing?.id
    ? `${context.wordpress_api_url}/posts/${existing.id}`
    : `${context.wordpress_api_url}/posts`
} }];

const response = $json;
const context = $('Choose WordPress Create or Update').first().json;
if (!response?.id || response?.status !== 'publish' || !response?.link) {
  throw new Error('WordPress did not return a published post ID and URL.');
}
if (String(response.slug || '') !== context.slug) throw new Error('WordPress returned a different slug than the approved package.');
if (Number(response.featured_media) !== Number(context.uploaded_featured_image_media_id)) throw new Error('WordPress did not retain the automatically uploaded topic image.');
return [{ json: {
  article_id: context.article_id,
  doctor_id: context.doctor_id,
  campaign_id: context.campaign_id,
  current_version: Number(context.current_version),
  publisher_config_reference: context.publisher_config_reference,
  external_post_id: String(response.id),
  published_url: String(response.link),
  wordpress_status: response.status,
  slug: response.slug || context.slug
} }];

const context = $('Prepare WordPress Publication').first().json;
const candidates = $input.all().flatMap((item) => Array.isArray(item.json) ? item.json : [item.json]).filter((item) => item?.id);
const reusable = candidates.find((item) => String(item.slug || '') === context.featured_image_media_slug) || null;
return [{ json: { ...context, media_exists: Boolean(reusable), reusable_media: reusable } }];

const media = $json.reusable_media;
if (!media?.id) throw new Error('The reusable topic image record is missing.');
return [{ json: media }];

const media = $json;
const context = $('Prepare WordPress Publication').first().json;
if (!media?.id || !/^image\//i.test(String(media.mime_type || ''))) throw new Error('WordPress did not return a valid uploaded image.');
const mediaUrl = String(media.source_url || media.guid?.rendered || '').trim();
if (!mediaUrl.startsWith(context.wordpress_publication_base_url + '/wp-content/uploads/')) throw new Error('WordPress returned an image outside the target subsite.');
const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[character]));
const figure = '<figure class="article-featured-image"><img src="' + escapeHtml(mediaUrl) + '" alt="' + escapeHtml(context.featured_image_alt_text) + '"></figure>';
const content = context.content.replace(/(<p\b[^>]*class=["'][^"']*\barticle-byline\b[^"']*["'][^>]*>[\s\S]*?<\/p>)/i, '$1\n' + figure);
return [{ json: { ...context, content, uploaded_featured_image_media_id: Number(media.id), uploaded_featured_image_url: mediaUrl, wordpress_body: { ...context.wordpress_body, content, featured_media: Number(media.id) } } }];
